// Simple Asteroid Escape game
// Canvas with id="game" must exist in the HTML
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // Ship definition (triangle)
  const ship = {
    x: width / 2,
    y: height * 0.85,
    size: 20,
    speed: 4,
    dx: 0,
    dy: 0,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.size);
      ctx.lineTo(this.x - this.size, this.y + this.size);
      ctx.lineTo(this.x + this.size, this.y + this.size);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      this.x += this.dx;
      this.y += this.dy;
      // keep inside canvas
      this.x = Math.max(this.size, Math.min(width - this.size, this.x));
    }
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });
  function handleInput() {
    ship.dx = 0;
    ship.dy = 0;
    if (keys.ArrowLeft) ship.dx = -ship.speed;
    if (keys.ArrowRight) ship.dx = ship.speed;
    if (keys.ArrowUp) ship.dy = -ship.speed;
    if (keys.ArrowDown) ship.dy = ship.speed;
  }

  // Asteroid class
  class Asteroid {
    constructor() {
      this.r = Math.random() * 15 + 10;
      this.x = Math.random() * (width - 2 * this.r) + this.r;
      this.y = -this.r;
      this.speed = Math.random() * 2 + 1;
    }
    update() { this.y += this.speed; }
    draw() {
      ctx.fillStyle = '#aaa';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
      ctx.fill();
    }
    offScreen() { return this.y - this.r > height; }
  }

  const asteroids = [];
  let lastSpawn = 0;
  const spawnInterval = 1000; // ms

  // Scoring
  let startTime = performance.now();
  let score = 0;

  function spawnAsteroid(now) {
    if (now - lastSpawn > spawnInterval) {
      asteroids.push(new Asteroid());
      lastSpawn = now;
    }
  }

  function checkCollision(a) {
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const dist = Math.hypot(dx, dy);
    // Approximate ship as circle with radius ship.size
    return dist < a.r + ship.size;
  }

  function update(now) {
    ctx.clearRect(0, 0, width, height);
    handleInput();
    ship.update();
    ship.draw();

    spawnAsteroid(now);
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.update();
      a.draw();
      if (checkCollision(a)) {
        // Game over
        alert('Game Over! Score: ' + Math.floor(score));
        // Reset
        asteroids.length = 0;
        startTime = performance.now();
        score = 0;
        return; // stop this frame
      }
      if (a.offScreen()) asteroids.splice(i, 1);
    }
    // Update score based on time survived
    score = (now - startTime) / 1000;
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    requestAnimationFrame(update);
  }

  requestAnimationFrame(update);
})();
